import React, { useState } from "react";
import NuovoIntervento from "../components/NuovoIntervento";
import MappaClienti from "../components/MappaClienti";
import CreaUtente from "../components/CreaUtente";
import ListaUtenti from "../components/ListaUtenti";

const DashboardAdmin = () => {
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [coordinate, setCoordinate] = useState(null);

  const handleSelect = (cliente) => {
    if (!cliente) {
      setClienteSelezionato(null);
      setCoordinate(null);
      return;
    }

    setClienteSelezionato(cliente);

    const lat = parseFloat(cliente.lat || cliente.posizione?.lat);
    const lng = parseFloat(cliente.lng || cliente.posizione?.lng);

    if (!isNaN(lat) && !isNaN(lng)) {
      setCoordinate({ lat, lng });
    } else {
      console.warn("⚠️ Coordinate non valide per il cliente selezionato");
      setCoordinate(null);
    }
  };

  return (
    <div className="container-fluid">
      <h3 className="mb-4">📋 Dashboard Amministratore</h3>

      {/* 🛠️ Nuovo intervento */}
      <div className="p-3 border rounded bg-light mb-4">
        <h5 className="mb-3">🛠️ Crea Nuovo Intervento</h5>
        <NuovoIntervento onSelectCliente={handleSelect} />
      </div>

      {/* 📍 Mappa cliente selezionato */}
      {coordinate && clienteSelezionato && (
        <div className="p-3 border rounded bg-light mb-4">
          <h5 className="mb-3">📍 Posizione Cliente</h5>
          <MappaClienti
            coordinate={coordinate}
            nome={
              clienteSelezionato.ragioneSociale ||
              clienteSelezionato.Cliente ||
              "Cliente"
            }
          />
        </div>
      )}

      {/* 👤 Creazione nuovo utente */}
      <div className="p-3 border rounded bg-light mb-4">
        <h5 className="mb-3">➕ Crea Nuovo Utente</h5>
        <CreaUtente />
      </div>

      {/* 📋 Elenco utenti */}
      <div className="p-3 border rounded bg-light mb-4">
        <h5 className="mb-3">📋 Elenco Utenti Registrati</h5>
        <ListaUtenti />
      </div>
    </div>
  );
};

export default DashboardAdmin;