import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Popup, Marker } from "react-leaflet";
import MarkerClusterGroup from "react-leaflet-cluster";
import { collection, getDocs, doc, updateDoc } from "firebase/firestore";
import { db } from "../services/firebase.js";
import L from "leaflet";
import {
  fromAddress,
  setKey,
  setLanguage,
  setRegion,
  setLocationType
} from "react-geocode";
import "leaflet/dist/leaflet.css";
import "react-leaflet-cluster/dist/assets/MarkerCluster.css";
import "react-leaflet-cluster/dist/assets/MarkerCluster.Default.css";

// 🔑 Configura la tua Google Maps API Key
setKey("AIzaSyCEioYKP8rJxdsztoQ3xnJiD27k-s5Pvsg");
setLanguage("it");
setRegion("it");
setLocationType("ROOFTOP");

const MappaClientiCluster = () => {
  const [clienti, setClienti] = useState([]);
  const [centroMappa, setCentroMappa] = useState([44.6, 10.6]);

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const clientiRaw = snapshot.docs.map(docSnap => ({
          id: docSnap.id,
          ...docSnap.data()
        }));

        const clientiConCoordinate = await Promise.all(
          clientiRaw.map(async cliente => {
            if (cliente.posizione?.lat && cliente.posizione?.lng) return cliente;

            const indirizzo = cliente.indirizzo || `${cliente.via || ""}, ${cliente.cap || ""} ${cliente.citta || ""}`;
            if (!indirizzo.trim()) return null;

            try {
              const res = await fromAddress(indirizzo);
              const { lat, lng } = res.results[0].geometry.location;
              const posizione = { lat, lng };

              // 🔄 Salva le coordinate nel documento Firestore
              await updateDoc(doc(db, "CLIENTI", cliente.id), { posizione });

              return { ...cliente, posizione };
            } catch (err) {
              console.warn("❌ Geocoding fallito per:", indirizzo, err);
              return null;
            }
          })
        );

        const filtrati = clientiConCoordinate.filter(Boolean);
        setClienti(filtrati);
      } catch (error) {
        console.error("Errore nel caricamento clienti:", error);
      }
    };

    fetchClienti();

    navigator.geolocation.getCurrentPosition(
      pos => {
        const { latitude, longitude } = pos.coords;
        setCentroMappa([latitude, longitude]);
      },
      err => console.warn("Geolocalizzazione utente fallita:", err),
      { enableHighAccuracy: true }
    );
  }, []);

  const markerIcon = new L.Icon({
    iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
    iconSize: [25, 41],
    iconAnchor: [12, 41],
    popupAnchor: [1, -34],
    shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
    shadowSize: [41, 41]
  });

  return (
    <div className="mb-4">
      <h5>🗺️ Cluster Geografico Clienti</h5>
      <MapContainer
        center={centroMappa}
        zoom={6}
        style={{ height: "500px", width: "100%", borderRadius: "8px" }}
        scrollWheelZoom={true}
      >
        <TileLayer
          attribution='© OpenStreetMap'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <MarkerClusterGroup>
          {clienti.map((c, idx) => (
            <Marker
              key={idx}
              position={[c.posizione.lat, c.posizione.lng]}
              icon={markerIcon}
            >
              <Popup>
                <strong>{c.ragioneSociale || c.nome || "Cliente"}</strong><br />
                {c.indirizzo || "Indirizzo non disponibile"}
              </Popup>
            </Marker>
          ))}
        </MarkerClusterGroup>
      </MapContainer>
    </div>
  );
};

export default MappaClientiCluster;