import React from "react";
import Badge from "react-bootstrap/Badge";

/**
 * Visualizza un badge colorato in base allo stato dell'intervento.
 * @param {Object} props
 * @param {string} props.stato - Stato dell'intervento (es. "Effettuato", "Programmato", "In Ritardo")
 */
const BadgeStato = ({ stato = "Non definito" }) => {
  const colori = {
    effettuato: "success",
    programmato: "warning",
    "in ritardo": "danger",
    "non definito": "secondary"
  };

  const chiave = stato.trim().toLowerCase();
  const variante = colori[chiave] || "secondary";

  return (
    <Badge bg={variante}>
      {stato}
    </Badge>
  );
};

export default BadgeStato;