import React from "react";
import { NavLink } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import {
  FaHome, FaUsers, FaTools, FaClipboardList,
  FaMapMarkedAlt, FaChartBar, FaUserCog, FaKey,
  FaCalendarAlt, FaSignOutAlt
} from "react-icons/fa";
import "./SidebarMobile.css";

const SidebarMobile = () => {
  const { ruolo } = useAuth();

  const menuConfig = {
    admin: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Clienti", path: "/clienti", icon: <FaUsers /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Interventi", path: "/report", icon: <FaClipboardList /> },
      { label: "Report", path: "/report-statistiche", icon: <FaChartBar /> },
      { label: "Utenti", path: "/utenti", icon: <FaUserCog /> },
      { label: "Manutenzioni Programmate", path: "/calendario-programmati", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Cambio Password", path: "/recupero", icon: <FaKey /> },
      { label: "Esci", path: "/logout", icon: <FaSignOutAlt /> },
    ],
    tecnico: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Interventi", path: "/report", icon: <FaClipboardList /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Mappa", path: "/mappa-clienti", icon: <FaMapMarkedAlt /> },
      { label: "Manutenzioni Programmate", path: "/calendario-programmati", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Cambio Password", path: "/recupero", icon: <FaKey /> },
      { label: "Esci", path: "/logout", icon: <FaSignOutAlt /> },
    ]
  };

  const menu = menuConfig[ruolo] || [];

  return (
    <div className="sidebar-mobile">
      <nav className="sidebar-mobile-nav">
        {menu.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) =>
              `sidebar-mobile-link ${isActive ? "active" : ""}`
            }
            end
          >
            {item.icon}
            <span className="sidebar-mobile-label">{item.label}</span>
          </NavLink>
        ))}
      </nav>
    </div>
  );
};

export default SidebarMobile;