import React from "react";
import { NavLink } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import {
  FaHome, FaUsers, FaTools, FaClipboardList,
  FaMapMarkedAlt, FaChartBar, FaUserCog, FaKey,
  FaCalendarAlt, FaSignOutAlt
} from "react-icons/fa";
import "./Sidebar.css";

const Sidebar = () => {
  const { ruolo } = useAuth();

  const menuConfig = {
    admin: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Clienti", path: "/clienti", icon: <FaUsers /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Report Interventi", path: "/report", icon: <FaChartBar /> },
      { label: "Utenti", path: "/utenti", icon: <FaUserCog /> },
      { label: "Calendario Manutenzioni", path: "/manutenzioni-programmate/calendario", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Cambio Password", path: "/recupero", icon: <FaKey /> },
      { label: "Esci", path: "/logout", icon: <FaSignOutAlt /> }
    ],
    tecnico: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Report Interventi", path: "/report", icon: <FaChartBar /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Mappa Clienti", path: "/mappa-clienti", icon: <FaMapMarkedAlt /> },
      { label: "Calendario Manutenzioni", path: "/manutenzioni-programmate/calendario", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Cambio Password", path: "/recupero", icon: <FaKey /> },
      { label: "Esci", path: "/logout", icon: <FaSignOutAlt /> }
    ]
  };

  const menu = menuConfig[ruolo] || [];

  return (
    <aside className="sidebar" role="navigation" aria-label={`Menù ${ruolo || "utente"}`}>
      <img
        src={`${process.env.PUBLIC_URL}/logo.png`}
        alt="Logo Aziendale"
        className="sidebar-logo"
      />
      <h2 className="sidebar-title">Menù {ruolo || "utente"}</h2>
      <nav className="sidebar-nav">
        {menu.map(({ label, path, icon }) => (
          <NavLink
            key={path}
            to={path}
            className={({ isActive }) => `sidebar-link${isActive ? " active" : ""}`}
            end
          >
            <span className="sidebar-icon">{icon}</span>
            <span className="sidebar-label">{label}</span>
          </NavLink>
        ))}
      </nav>
    </aside>
  );
};

export default Sidebar;