import React from "react";
import { CSVLink } from "react-csv";
import PropTypes from "prop-types";

/**
 * Esporta un array di oggetti in formato CSV.
 * @param {Object} props
 * @param {Array} props.dati - Array di oggetti da esportare
 * @param {Array} props.intestazioni - Array di { label, key } per le colonne
 * @param {string} props.nomeFile - Nome del file CSV
 * @param {string} props.className - Classe CSS per il bottone
 * @param {string} props.separator - Separatore CSV (default ";")
 */
function CsvExport({
  dati = [],
  intestazioni = [],
  nomeFile = "export.csv",
  className = "btn btn-outline-primary",
  separator = ";"
}) {
  const haDati = Array.isArray(dati) && dati.length > 0;

  return haDati ? (
    <CSVLink
      data={dati}
      headers={intestazioni}
      filename={nomeFile}
      className={className}
      separator={separator}
      target="_blank"
      aria-label="Esporta CSV"
      title="Esporta i dati in formato CSV"
    >
      📤 Esporta CSV
    </CSVLink>
  ) : (
    <button
      className="btn btn-outline-secondary"
      disabled
      aria-label="CSV vuoto"
      title="Nessun dato da esportare"
    >
      📄 CSV vuoto
    </button>
  );
}

CsvExport.propTypes = {
  dati: PropTypes.arrayOf(PropTypes.object),
  intestazioni: PropTypes.arrayOf(
    PropTypes.shape({
      label: PropTypes.string.isRequired,
      key: PropTypes.string.isRequired
    })
  ),
  nomeFile: PropTypes.string,
  className: PropTypes.string,
  separator: PropTypes.string
};

export default CsvExport;