import React, { useEffect, useState } from "react";
import { collection, onSnapshot, query, orderBy } from "firebase/firestore";
import { db } from "../services/firebase.js";
import { Calendar, dateFnsLocalizer } from "react-big-calendar";
import format from "date-fns/format";
import parse from "date-fns/parse";
import startOfWeek from "date-fns/startOfWeek";
import getDay from "date-fns/getDay";
import it from "date-fns/locale/it";
import "react-big-calendar/lib/css/react-big-calendar.css";

const locales = { it };
const localizer = dateFnsLocalizer({ format, parse, startOfWeek, getDay, locales });

const CalendarioManutenzioni = () => {
  const [eventiCalendario, setEventiCalendario] = useState([]);

  useEffect(() => {
    const q = query(collection(db, "ManutenzioniProgrammate"), orderBy("prossimaData", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const eventi = snapshot.docs.map(doc => {
        const data = doc.data();
        const dataEvento = data.prossimaData?.toDate ? data.prossimaData.toDate() : new Date(data.prossimaData);

        return {
          title: `${data.cliente} – ${data.mezzo}`,
          start: dataEvento,
          end: dataEvento,
          allDay: true,
          resource: data
        };
      });
      setEventiCalendario(eventi);
    });
    return () => unsubscribe();
  }, []);

  const handleSelectEvent = (event) => {
    const { cliente, mezzo, frequenza, prossimaData } = event.resource;
    alert(`📅 Manutenzione programmata:\nCliente: ${cliente}\nMezzo: ${mezzo}\nFrequenza: ${frequenza}\nScadenza: ${prossimaData}`);
  };

  return (
    <div className="p-4">
      <h3 className="mb-4">🗓 Calendario Manutenzioni Programmate</h3>
      <Calendar
        localizer={localizer}
        events={eventiCalendario}
        startAccessor="start"
        endAccessor="end"
        style={{ height: 600 }}
        onSelectEvent={handleSelectEvent}
        views={["month", "week", "day"]}
        messages={{
          month: "Mese",
          week: "Settimana",
          day: "Giorno",
          today: "Oggi",
          agenda: "Agenda"
        }}
      />
    </div>
  );
};

export default CalendarioManutenzioni;