import React, { useState } from "react";
import { createUserWithEmailAndPassword } from "firebase/auth";
import { collection, addDoc, getDocs, query, where } from "firebase/firestore";
import { auth, db } from "../services/firebase";
import { toast } from "react-hot-toast";

const CreaUtente = () => {
  const [form, setForm] = useState({
    nome: "",
    email: "",
    password: "",
    confermaPassword: "",
    ruolo: "tecnico"
  });

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const isPasswordForte = password => {
    const regex = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{6,}$/;
    return regex.test(password);
  };

  const handleSubmit = async e => {
    e.preventDefault();

    if (form.password !== form.confermaPassword) {
      toast.error("⚠️ Le password non coincidono.");
      return;
    }

    if (!isPasswordForte(form.password)) {
      toast.error("🔐 La password deve contenere almeno 6 caratteri, una lettera e un numero.");
      return;
    }

    try {
      const q = query(collection(db, "UTENTI"), where("Email", "==", form.email));
      const snapshot = await getDocs(q);

      if (!snapshot.empty) {
        toast.error("⚠️ L'email è già associata a un utente esistente.");
        return;
      }

      const userCred = await createUserWithEmailAndPassword(
        auth,
        form.email,
        form.password
      );

      await addDoc(collection(db, "UTENTI"), {
        UID: userCred.user.uid,
        Nome: form.nome,
        Email: form.email,
        Ruolo: form.ruolo,
        CreatedAt: new Date()
      });

      toast.success("✅ Utente creato con successo!");
      setForm({
        nome: "",
        email: "",
        password: "",
        confermaPassword: "",
        ruolo: "tecnico"
      });

    } catch (error) {
      if (error.code === "auth/email-already-in-use") {
        toast.error("⚠️ L'email è già registrata in Firebase Authentication.");
      } else {
        toast.error("❌ Errore: " + error.message);
      }
      console.error("Errore nella creazione utente:", error);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <div className="row g-3">
        <div className="col-md-4">
          <input
            type="text"
            name="nome"
            value={form.nome}
            onChange={handleChange}
            className="form-control"
            placeholder="Nome completo"
            required
          />
        </div>
        <div className="col-md-4">
          <input
            type="email"
            name="email"
            value={form.email}
            onChange={handleChange}
            className="form-control"
            placeholder="Email"
            required
          />
        </div>
        <div className="col-md-4">
          <input
            type="password"
            name="password"
            value={form.password}
            onChange={handleChange}
            className="form-control"
            placeholder="Password"
            required
          />
        </div>
        <div className="col-md-4">
          <input
            type="password"
            name="confermaPassword"
            value={form.confermaPassword}
            onChange={handleChange}
            className="form-control"
            placeholder="Conferma Password"
            required
          />
        </div>
        <div className="col-md-3">
          <select
            name="ruolo"
            value={form.ruolo}
            onChange={handleChange}
            className="form-select"
          >
            <option value="tecnico">Tecnico</option>
            <option value="admin">Admin</option>
          </select>
        </div>
        <div className="col-md-3">
          <button type="submit" className="btn btn-success w-100">
            ➕ Crea Utente
          </button>
        </div>
      </div>
    </form>
  );
};

export default CreaUtente;