import React, { useEffect, useState } from "react";
import { Calendar, dateFnsLocalizer } from "react-big-calendar";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase.js";

import format from "date-fns/format";
import parse from "date-fns/parse";
import startOfWeek from "date-fns/startOfWeek";
import getDay from "date-fns/getDay";
import it from "date-fns/locale/it";

import "react-big-calendar/lib/css/react-big-calendar.css";

const locales = { it };
const localizer = dateFnsLocalizer({
  format,
  parse,
  startOfWeek: () => startOfWeek(new Date(), { weekStartsOn: 1 }),
  getDay,
  locales,
});

const CalendarioInterventi = () => {
  const [eventi, setEventi] = useState([]);

  useEffect(() => {
    const fetchInterventi = async () => {
      try {
        const snapshot = await getDocs(collection(db, "INTERVENTI"));
        const lista = snapshot.docs.map((doc) => {
          const data = doc.data();
          const titolo = `${data.ragioneSociale || "Cliente"} - ${data.categoria || "Intervento"}`;

          const start = data.dataIntervento?.seconds
            ? new Date(data.dataIntervento.seconds * 1000)
            : new Date();

          const end = data.prossimoIntervento?.seconds
            ? new Date(data.prossimoIntervento.seconds * 1000)
            : new Date(start.getTime() + 2 * 60 * 60 * 1000); // default 2h

          return {
            id: doc.id,
            title: titolo,
            start,
            end,
            allDay: false,
          };
        });

        setEventi(lista);
      } catch (error) {
        console.error("❌ Errore nel caricamento interventi:", error);
      }
    };

    fetchInterventi();
  }, []);

  return (
    <div className="mt-5">
      <h4 className="mb-3">🗓️ Calendario Interventi</h4>
      <Calendar
        localizer={localizer}
        events={eventi}
        startAccessor="start"
        endAccessor="end"
        style={{ height: 600 }}
        views={["month", "week", "day"]}
        popup
        messages={{
          today: "Oggi",
          previous: "←",
          next: "→",
          month: "Mese",
          week: "Settimana",
          day: "Giorno",
          agenda: "Agenda",
        }}
      />
    </div>
  );
};

export default CalendarioInterventi;