import React, { useEffect, useState } from "react";
import { collection, getDocs, doc, updateDoc, deleteDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import { toast } from "react-hot-toast";

const ListaUtenti = () => {
  const [utenti, setUtenti] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({ nome: "", ruolo: "" });

  const fetchUtenti = async () => {
    const snapshot = await getDocs(collection(db, "UTENTI"));
    const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    setUtenti(lista);
  };

  useEffect(() => {
    fetchUtenti();
  }, []);

  const handleEdit = utente => {
    setEditingId(utente.id);
    setEditForm({ nome: utente.Nome, ruolo: utente.Ruolo });
  };

  const handleEditChange = e => {
    setEditForm({ ...editForm, [e.target.name]: e.target.value });
  };

  const handleSave = async id => {
    try {
      const ref = doc(db, "UTENTI", id);
      await updateDoc(ref, {
        Nome: editForm.nome,
        Ruolo: editForm.ruolo
      });
      toast.success("✅ Utente aggiornato");
      setEditingId(null);
      fetchUtenti();
    } catch (error) {
      toast.error("❌ Errore aggiornamento");
      console.error(error);
    }
  };

  const handleDelete = async id => {
    const conferma = window.confirm("Sei sicuro di voler eliminare questo utente?");
    if (!conferma) return;

    try {
      await deleteDoc(doc(db, "UTENTI", id));
      toast.success("🗑️ Utente eliminato");
      fetchUtenti();
    } catch (error) {
      toast.error("❌ Errore eliminazione");
      console.error(error);
    }
  };

  return (
    <div className="table-responsive">
      <table className="table table-bordered align-middle">
        <thead className="table-light">
          <tr>
            <th>Nome</th>
            <th>Email</th>
            <th>Ruolo</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          {utenti.map(utente => (
            <tr key={utente.id}>
              <td>
                {editingId === utente.id ? (
                  <input
                    type="text"
                    name="nome"
                    value={editForm.nome}
                    onChange={handleEditChange}
                    className="form-control"
                  />
                ) : (
                  utente.Nome
                )}
              </td>
              <td>{utente.Email}</td>
              <td>
                {editingId === utente.id ? (
                  <select
                    name="ruolo"
                    value={editForm.ruolo}
                    onChange={handleEditChange}
                    className="form-select"
                  >
                    <option value="tecnico">Tecnico</option>
                    <option value="admin">Admin</option>
                  </select>
                ) : (
                  utente.Ruolo
                )}
              </td>
              <td>
                {editingId === utente.id ? (
                  <button
                    onClick={() => handleSave(utente.id)}
                    className="btn btn-sm btn-success me-2"
                  >
                    💾 Salva
                  </button>
                ) : (
                  <button
                    onClick={() => handleEdit(utente)}
                    className="btn btn-sm btn-warning me-2"
                  >
                    ✏️ Modifica
                  </button>
                )}
                <button
                  onClick={() => handleDelete(utente.id)}
                  className="btn btn-sm btn-danger"
                >
                  🗑️ Elimina
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ListaUtenti;